const copy=x=>JSON.parse(JSON.stringify(x));
const initial=()=>({cases:copy(D.cases),activeId:D.cases[0].id,compare:D.cases.slice(0,3).map(c=>c.id),chat:[],ui:{},version:1});
// Validate saved browser data before using it. Older deployments used different case shapes.
function recoverState(saved){
  const clean=initial();
  if(!saved || !Array.isArray(saved.cases))return clean;
  const isObject=x=>x!==null && typeof x==='object' && !Array.isArray(x);
  clean.cases=clean.cases.map(base=>{
    const prev=saved.cases.find(x=>isObject(x)&&x.id===base.id);
    if(!prev)return base;
    const result={...base};
    const ratings={...base.ratings};
    if(isObject(prev.ratings))for(const k of Object.keys(ratings)){
      const v=prev.ratings[k];
      if(v===null||v==='')ratings[k]=null;
      else if(typeof v==='number' && Number.isFinite(v) && v>=1 && v<=5)ratings[k]=v;
    }
    result.ratings=ratings;
    result.finance={...base.finance};
    if(isObject(prev.finance))for(const [k,def] of Object.entries(base.finance)){
      const v=prev.finance[k];
      if(typeof def==='number' && typeof v==='number' && Number.isFinite(v) && v>=0)result.finance[k]=v;
      else if(typeof def==='boolean'&&typeof v==='boolean')result.finance[k]=v;
      else if(typeof def==='string'&&typeof v==='string'&&v.length<200)result.finance[k]=v;
    }
    const validCandidates=new Set(D.interventions.map(x=>x.id));
    result.selected=Array.isArray(prev.selected)?[...new Set(prev.selected.filter(x=>validCandidates.has(x)))]:base.selected;
    result.questionnaire=isObject(prev.questionnaire)?Object.fromEntries(Object.entries(prev.questionnaire).filter(([k,v])=>D.criteria.some(x=>x.code===k)&&(v===null||(typeof v==='number'&&v>=1&&v<=5)))):base.questionnaire;
    result.workflowNotes=isObject(prev.workflowNotes)?Object.fromEntries(Object.entries(prev.workflowNotes).filter(([k,v])=>/^[1-8]$/.test(k)&&typeof v==='string').map(([k,v])=>[k,v.slice(0,25000)])):base.workflowNotes;
    if(Number.isInteger(prev.completed_stage)&&prev.completed_stage>=0&&prev.completed_stage<=8)result.completed_stage=prev.completed_stage;
    if(typeof prev.diagnosis_approved==='boolean')result.diagnosis_approved=prev.diagnosis_approved;
    if(typeof prev.reviewDecision==='string'&&prev.reviewDecision.length<80)result.reviewDecision=prev.reviewDecision;
    if(typeof prev.reviewNote==='string')result.reviewNote=prev.reviewNote.slice(0,5000);
    return result;
  });
  if(clean.cases.some(x=>x.id===saved.activeId))clean.activeId=saved.activeId;
  if(Array.isArray(saved.compare)){
    const picked=[...new Set(saved.compare.filter(id=>clean.cases.some(c=>c.id===id)))].slice(0,3);
    if(picked.length)clean.compare=picked;
  }
  if(Array.isArray(saved.chat))clean.chat=saved.chat.filter(x=>isObject(x)&&typeof x.sid==='string'&&typeof x.text==='string'&&(x.role==='user'||x.role==='bot')).slice(-80);
  if(isObject(saved.ui))clean.ui={interventionDomain:['A','B','C','ALL'].includes(saved.ui.interventionDomain)?saved.ui.interventionDomain:'ALL'};
  return clean;
}
let state=initial();
let backendEvaluations={};
let backendReady=false;
let saveQueue=Promise.resolve();
let saveFailures=0;
function save(){
  // Serialize state writes, so quick edits cannot arrive at the API out of order.
  const snapshot=JSON.stringify(state);
  backendEvaluations={}; // UI can calculate a provisional result until API confirms it.
  saveQueue=saveQueue.catch(()=>{}).then(async()=>{
    const resp=await fetch('/api/state',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:snapshot});
    if(!resp.ok){const error=await resp.json().catch(()=>({detail:'Request failed'}));throw Error(error.detail||'Unable to save');}
    const data=await resp.json();
    backendEvaluations=data.evaluations||{};
    saveFailures=0;
    const status=document.getElementById('backend-save-status');
    if(status){status.textContent='Saved to server';status.classList.remove('offline');}
  }).catch(async err=>{
    saveFailures++;
    const status=document.getElementById('backend-save-status');
    if(status){status.textContent='Not saved';status.classList.add('offline');}
    console.error('Backend save failed:',err);
    try{
      const restored=await fetch('/api/bootstrap',{credentials:'same-origin',cache:'no-store'});
      if(restored.ok){const data=await restored.json();state=recoverState(data.state);backendEvaluations=data.evaluations||{};render();}
    }catch(recoveryError){console.error('Recovery failed:',recoveryError);}
    toast('Not saved: '+String(err.message||'Server rejected the change').slice(0,140));
  });
  const status=document.getElementById('backend-save-status');if(status)status.textContent='Saving…';
  return saveQueue;
}
