function calc(s){if(backendEvaluations[s.id]){const x=backendEvaluations[s.id];return{p:x.p,cost:x.cost,gain:x.gain,net:x.net,sup:x.sup,econ:x.econ};}let f=s.finance;let p=Number(f.p_technical||0)*Number(f.p_on_time||0)*Number(f.p_sustain||0);let cost=['cost_experts','cost_travel','cost_testing','cost_tooling','cost_incentives'].reduce((a,k)=>a+Number(f[k]||0),0);let gain=Number(f.gain||0),net=gain*p-cost;let sup=Number(f.supplier_contribution||0)+Number(f.retained_savings||0)+Number(f.productivity_relief||0)+Number(f.other_customer_upside||0)-Number(f.supplier_capex||0)-Number(f.supplier_opex||0);return{p,cost,gain,net,sup,econ:net>0}};
function domainStats(s,k){const a=D.criteria.filter(x=>x.code.startsWith(k)).map(x=>s.ratings[x.code]).filter(v=>v!=null&&v!==''&&Number.isFinite(+v));return{n:a.length,total:D.criteria.filter(x=>x.code.startsWith(k)).length,avg:a.length?a.reduce((u,v)=>u+Number(v),0)/a.length:null}}
function coverage(s){let rated=Object.values(s.ratings||{}).filter(x=>x!=null&&x!=='').length;return{rated,total:D.criteria.length,rate:rated/D.criteria.length}}
function missing(s){return D.criteria.filter(x=>s.ratings[x.code]==null).map(x=>x.code)}
function weak(s){return D.criteria.filter(x=>s.ratings[x.code]!=null&&Number(s.ratings[x.code])<3.1).sort((a,b)=>Number(s.ratings[a.code])-Number(s.ratings[b.code]))}
function interventionMatches(s){if(backendEvaluations[s.id]?.recommendations?.length){return backendEvaluations[s.id].recommendations.map(i=>({...i,keys:i.criteria_list}));}const gaps=new Set([...weak(s).map(x=>x.code),...(s.criteria||[])]);return D.interventions.map(i=>{let keys=i.criteria.split(';').map(x=>x.trim());let overlap=keys.filter(k=>gaps.has(k)),knownWeak=keys.filter(k=>s.ratings[k]!=null&&Number(s.ratings[k])<3.1);return{...i,keys,overlap,points:knownWeak.length*4+overlap.length*2+(s.selected||[]).includes(i.id)}}).sort((a,b)=>b.points-a.points)}
const scoreColor=v=>v===null?'muted':v>=3.1?'green':'amber';
function scoreTag(v){return v==null?tag('Not assessed','line'):tag(v.toFixed(2)+' / 5',scoreColor(v))}
